package cn.bidcheck.verification.engine;

import cn.bidcheck.domain.Domain.Document;
import cn.bidcheck.domain.Domain.Page;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import java.util.*;
import static cn.bidcheck.verification.engine.VerificationTypes.*;
import static org.junit.jupiter.api.Assertions.*;

/** Source-backed synthetic personnel fixtures; no model, service, database, or external requests. */
class PersonnelCountRoleTest {
    final ObjectMapper json=new ObjectMapper();
    EvidenceCorpus corpus(String... text){List<Page> pages=new ArrayList<>();for(int i=0;i<text.length;i++)pages.add(new Page(i+1,text[i],"PAGE","PDF",""));return new EvidenceCorpus(List.of(new Document("d","p","BID","fixture.pdf",1,"hash","",pages,List.of())));}
    Source source(EvidenceCorpus c,int page){return c.all.stream().filter(s->s.evidence().page()==page).findFirst().orElseThrow();}
    String appointment(String role,String name,String id,String employer,String lot){return "本项目"+employer+lot+role+"："+name+(id.isBlank()?"":" 身份证号码："+id);}
    Fact role(EvidenceCorpus c,int page,String role,String name,String employer,String lot){return new Fact("f:"+page+":"+role+":"+name,"PERSON_ROLE",role,"role",name,name,"","","CURRENT_PROJECT",List.of(source(c,page).id()),Map.of("employer",employer,"lot",lot));}
    List<Fact> checked(EvidenceCorpus c,Fact... facts){var verified=new ProofVerifier().verify(json.valueToTree(Map.of("facts",List.of(facts))),c.all);assertTrue(verified.rejected().isEmpty(),verified.rejected().toString());return verified.facts();}
    Rule count(String role,String op,String expected,String quote,Map<String,Object> params){return new Rule("r",quote,"PERSON_COUNT",role,"personCount",op,expected,"人",params,quote,"",List.of());}
    Rule count(String op,String number){String word=switch(op){case ">="->"至少";case "<="->"不超过";case "="->"恰好";case ">"->"超过";default->"少于";};return count("专职安全员",op,number,"专职安全员"+word+number+"人",Map.of());}
    Decision evaluate(EvidenceCorpus c,List<Fact> facts,Rule r){return new RuleEvaluator(facts,c,Map.of()).evaluate(r);}
    List<Fact> people(EvidenceCorpus c){List<Fact> facts=new ArrayList<>();for(int p=1;p<=c.documents.get(0).pages().size();p++)facts.add(role(c,p,"专职安全员",p==1?"张甲":p==2?"李乙":"王丙","",""));return checked(c,facts.toArray(Fact[]::new));}
    String roster(String names){return "本项目专职安全员完整名单："+names+"。\n";}

    @Test void recognizedExpandedRoleTitlesRemainDistinct(){assertTrue(DomainBindings.role("施工企业主要负责人"));assertTrue(DomainBindings.role("施工部分负责人"));assertTrue(DomainBindings.role("设计部分负责人"));assertTrue(DomainBindings.role("施工单位"));assertNotEquals(PersonnelRoles.canonical("企业主要负责人"),PersonnelRoles.canonical("项目负责人"));}
    @Test void currentConstructionPartRoleKeepsOriginalTitle(){EvidenceCorpus c=corpus(appointment("施工部分负责人","张甲","110101199001010011","",""));var facts=checked(c,role(c,1,"施工部分负责人","张甲","",""));assertEquals(List.of("张甲"),DomainBindings.subjects("施工负责人",facts,c));Rule r=new Rule("r","施工负责人任职","PERSON_ROLE","施工负责人","role","","","",Map.of(),"施工负责人任职","",List.of());Decision d=evaluate(c,facts,r);assertEquals("PASS",d.status(),d.toString());assertEquals("施工部分负责人",RuleEvaluator.maps(d.proof().get("roleBindings")).get(0).get("originalRole"));}
    @Test void historicalTitleDoesNotBecomeCurrentThroughNormalization(){EvidenceCorpus c=corpus("历史项目\n"+appointment("施工部分负责人","张甲","110101199001010011","",""));Fact f=role(c,1,"施工部分负责人","张甲","","");assertTrue(DomainBindings.subjects("施工负责人",List.of(f),c).isEmpty());}
    @Test void managerAndProjectPrincipalNeedExplicitCurrentAlias(){EvidenceCorpus c=corpus(appointment("项目经理","张甲","110101199001010011","",""));var facts=checked(c,role(c,1,"项目经理","张甲","",""));assertTrue(DomainBindings.subjects("项目负责人",facts,c).isEmpty());assertTrue(PersonnelRoles.queryTerms("项目负责人").contains("项目经理"));}
    @Test void explicitParentheticalTitleSupportsAliasOnlyWithAppointment(){EvidenceCorpus c=corpus("本项目项目负责人（项目经理）：张甲 身份证号码：110101199001010011");var facts=checked(c,role(c,1,"项目经理","张甲","",""));assertEquals(List.of("张甲"),DomainBindings.subjects("项目负责人",facts,c));}
    @Test void enterprisePrincipalCannotBecomeProjectPrincipal(){EvidenceCorpus c=corpus(appointment("施工企业主要负责人","张甲","110101199001010011","",""));var facts=checked(c,role(c,1,"施工企业主要负责人","张甲","",""));assertTrue(DomainBindings.subjects("项目负责人",facts,c).isEmpty());assertTrue(DomainBindings.subjects("企业主要负责人",facts,c).isEmpty());}
    @Test void unsupportedKnownRoleReportsUnsupportedBeforeRoleLookup(){EvidenceCorpus c=corpus("本项目资料");Rule r=new Rule("r","域外要求","UNSUPPORTED","投标人","","","","",Map.of(),"域外要求","",List.of());assertEquals("UNSUPPORTED_RULE",evaluate(c,List.of(),r).gaps().get(0).code());}
    @Test void bareOnePersonCannotBeTurnedIntoMinimumByModel(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","",""));Rule r=count("专职安全员",">=","1","专职安全员1人",Map.of("countComparisonBasis","EXPLICIT_COMPARATOR"));Decision d=evaluate(c,people(c),r);assertEquals("PERSON_COUNT_COMPARISON_REQUIRED",d.gaps().get(0).code());}
    @Test void sourceBareRoleConfigurationCanBeFilledWithoutProvingAnUpperBound(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","",""),appointment("专职安全员","李乙","110101199001010022","",""));Decision d=evaluate(c,people(c),count("专职安全员","","1","专职安全员1人",Map.of()));assertEquals("PASS",d.status(),d.toString());assertEquals("ROLE_CONFIGURATION_ONLY",d.proof().get("proofScope"));assertEquals(false,d.proof().get("upperBoundProven"));assertEquals(false,d.proof().get("exactCountProven"));assertEquals(false,d.proof().get("qualificationCountProven"));}
    @Test void singleConfigurationHasLocalExistenceWithoutInventingDistinctIdentity(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","","",""));Decision d=evaluate(c,people(c),count("专职安全员","","1","专职安全员1人",Map.of()));assertEquals("PASS",d.status());assertEquals(0,d.proof().get("provenDistinctPeople"));assertEquals(1,d.proof().get("provenExistenceLowerBound"));assertEquals(false,d.proof().get("globalIdentityProven"));}
    @Test void zeroOrNegatedOrHistoricalBareCountIsNotAStaffingRequirement(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","",""));for(String quote:List.of("无需专职安全员1人","历史项目专职安全员1人","例如专职安全员1人")){Decision d=evaluate(c,people(c),count("专职安全员","","1",quote,Map.of()));assertEquals("PERSON_COUNT_COMPARISON_REQUIRED",d.gaps().get(0).code(),quote);}assertEquals("UNDETERMINED",evaluate(c,people(c),count("专职安全员","","0","专职安全员0人",Map.of())).status());}
    @Test void operatorMustAgreeWithOriginalComparator(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","",""));assertEquals("PERSON_COUNT_COMPARISON_REQUIRED",evaluate(c,people(c),count("专职安全员",">=","1","专职安全员不超过1人",Map.of())).gaps().get(0).code());}
    @Test void explicitMinimumCanBeProvenWithoutExhaustiveRoster(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","",""));Decision d=evaluate(c,people(c),count(">=","1"));assertEquals("PASS",d.status(),d.toString());assertEquals(false,d.proof().get("populationComplete"));}
    @Test void repeatedMaterialsCountSameIdentityOnlyOnce(){String text=appointment("专职安全员","张甲","110101199001010011","","");EvidenceCorpus c=corpus(text,text);var facts=checked(c,role(c,1,"专职安全员","张甲","",""),role(c,2,"专职安全员","张甲","",""));Decision d=evaluate(c,facts,count(">=","2"));assertEquals("UNDETERMINED",d.status());assertEquals(1,d.proof().get("provenDistinctPeople"));}
    @Test void incompleteListCannotProveShortage(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","",""));assertEquals("PERSON_SET_INCOMPLETE",evaluate(c,people(c),count(">=","2")).gaps().get(0).code());}
    @Test void completeIdentityBoundListCanProveShortage(){EvidenceCorpus c=corpus(roster("张甲")+appointment("专职安全员","张甲","110101199001010011","",""));Decision d=evaluate(c,people(c),count(">=","2"));assertEquals("FAIL",d.status(),d.toString());assertEquals(true,d.proof().get("populationComplete"));}
    @Test void upperBoundNeedsCompleteListToPass(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","",""));assertEquals("UNDETERMINED",evaluate(c,people(c),count("<=","2")).status());}
    @Test void knownDistinctWitnessesCanProveUpperBoundExceeded(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","",""),appointment("专职安全员","李乙","110101199001010022","",""));assertEquals("FAIL",evaluate(c,people(c),count("<=","1")).status());}
    @Test void exactCountRequiresCompleteList(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","",""));assertEquals("UNDETERMINED",evaluate(c,people(c),count("=","1")).status());EvidenceCorpus full=corpus(roster("张甲")+appointment("专职安全员","张甲","110101199001010011","",""));assertEquals("PASS",evaluate(full,people(full),count("=","1")).status());}
    @Test void modelCompleteFlagCannotReplaceOriginalRoster(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","",""));Rule r=count("专职安全员",">=","2","专职安全员至少2人",Map.of("subjectSetComplete",true));assertEquals("UNDETERMINED",evaluate(c,people(c),r).status());}
    @Test void homonymIdentityAmbiguityCannotProveShortageOrSufficiency(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","",""),appointment("专职安全员","张甲","110101199001010022","",""));var fs=checked(c,role(c,1,"专职安全员","张甲","",""),role(c,2,"专职安全员","张甲","",""));assertEquals("PERSON_COUNT_IDENTITY_AMBIGUOUS",evaluate(c,fs,count(">=","1")).gaps().get(0).code());}
    @Test void unlabelledIdentityDoesNotIncreaseProvenCount(){EvidenceCorpus c=corpus(roster("张甲")+appointment("专职安全员","张甲","","",""));Decision d=evaluate(c,people(c),count(">=","1"));assertEquals("PERSON_COUNT_IDENTITY_REQUIRED",d.gaps().get(0).code());}
    @Test void differentMembersCannotBeAddedTogether(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","甲公司",""),appointment("专职安全员","李乙","110101199001010022","乙公司",""));var fs=checked(c,role(c,1,"专职安全员","张甲","甲公司",""),role(c,2,"专职安全员","李乙","乙公司",""));assertEquals("PERSON_COUNT_MEMBER_REQUIRED",evaluate(c,fs,count(">=","2")).gaps().get(0).code());}
    @Test void requestedEmployerFiltersOtherMembers(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","甲公司",""),appointment("专职安全员","李乙","110101199001010022","乙公司",""));var fs=checked(c,role(c,1,"专职安全员","张甲","甲公司",""),role(c,2,"专职安全员","李乙","乙公司",""));Decision d=evaluate(c,fs,count("专职安全员",">=","2","甲公司专职安全员至少2人",Map.of("employer","甲公司")));assertEquals("UNDETERMINED",d.status());assertEquals(1,d.proof().get("provenDistinctPeople"));}
    @Test void differentLotsCannotBeAddedTogether(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","","第一标段"),appointment("专职安全员","李乙","110101199001010022","","第二标段"));var fs=checked(c,role(c,1,"专职安全员","张甲","","第一标段"),role(c,2,"专职安全员","李乙","","第二标段"));assertEquals("PERSON_COUNT_LOT_REQUIRED",evaluate(c,fs,count(">=","2")).gaps().get(0).code());}
    @Test void narrowerMemberRosterCannotProveWholeProjectShortage(){EvidenceCorpus c=corpus("本项目甲公司专职安全员完整名单：张甲。\n"+appointment("专职安全员","张甲","110101199001010011","甲公司",""));var fs=checked(c,role(c,1,"专职安全员","张甲","甲公司",""));assertEquals("UNDETERMINED",evaluate(c,fs,count(">=","2")).status());}
    @Test void appointmentCountDoesNotCertifyQualifiedPersonnel(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","",""));Rule r=count("专职安全员",">=","1","持证专职安全员至少1人",Map.of());assertEquals("PERSON_COUNT_QUALIFICATION_UNPROVEN",evaluate(c,people(c),r).gaps().get(0).code());}
    @Test void completeRosterCannotBorrowNamesFromOtherSource(){EvidenceCorpus c=corpus(roster("张甲"),appointment("专职安全员","张甲","110101199001010011","",""));var fs=checked(c,role(c,2,"专职安全员","张甲","",""));assertEquals("UNDETERMINED",evaluate(c,fs,count(">=","2")).status());}
    @Test void nativeNumberAndReverseChineseComparatorAreSupported(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","",""));Rule r=count("专职安全员",">=","1","至少一名专职安全员",Map.of());assertEquals("PASS",evaluate(c,people(c),r).status());}
    @Test void differentNamesSharingAnIdentifierRemainAmbiguous(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","",""),appointment("专职安全员","李乙","110101199001010011","",""));assertEquals("PERSON_COUNT_IDENTITY_AMBIGUOUS",evaluate(c,people(c),count(">=","1")).gaps().get(0).code());}
    @Test void conflictingUnextractedRosterCannotProveShortage(){EvidenceCorpus c=corpus(roster("张甲")+appointment("专职安全员","张甲","110101199001010011","",""),roster("张甲、李乙"));var fs=checked(c,role(c,1,"专职安全员","张甲","",""));assertEquals("UNDETERMINED",evaluate(c,fs,count(">=","2")).status());}
    @Test void memberAndLotCompleteRosterProvesOnlyRequestedScope(){EvidenceCorpus c=corpus("本项目甲公司第一标段专职安全员完整名单：张甲。\n"+appointment("专职安全员","张甲","110101199001010011","甲公司","第一标段"));var fs=checked(c,role(c,1,"专职安全员","张甲","甲公司","第一标段"));Rule r=count("专职安全员","=","1","甲公司第一标段专职安全员恰好1人",Map.of("employer","甲公司","lot","第一标段"));assertEquals("PASS",evaluate(c,fs,r).status());Rule wrong=count("专职安全员",">=","1","甲公司第二标段专职安全员至少1人",Map.of("employer","甲公司","lot","第二标段"));assertEquals("UNDETERMINED",evaluate(c,fs,wrong).status());}
    @Test void employerDimensionDoesNotReplaceIndependentEmploymentProof(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","甲公司",""));var fs=checked(c,role(c,1,"专职安全员","张甲","甲公司",""));Rule r=count("专职安全员",">=","1","受聘于甲公司的专职安全员至少1人",Map.of("employer","甲公司"));assertEquals("EMPLOYMENT_RELATION_REQUIRED",evaluate(c,fs,r).gaps().get(0).code());}
    @Test void currentScopeFlagWithoutCurrentOriginalTextDoesNotCount(){EvidenceCorpus c=corpus("专职安全员：张甲 身份证号码：110101199001010011");Fact f=role(c,1,"专职安全员","张甲","","");Decision d=evaluate(c,List.of(f),count(">=","1"));assertEquals("UNDETERMINED",d.status());assertEquals(0,d.proof().get("provenDistinctPeople"));}
    @Test void unknownMemberCannotBeMergedIntoTheOnlyKnownMember(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","甲公司",""),appointment("专职安全员","李乙","110101199001010022","",""));var fs=checked(c,role(c,1,"专职安全员","张甲","甲公司",""),role(c,2,"专职安全员","李乙","",""));assertEquals("PERSON_COUNT_MEMBER_REQUIRED",evaluate(c,fs,count(">=","2")).gaps().get(0).code());}
    @Test void explicitlyStatedExactCountDoesNotBecomeABareCount(){EvidenceCorpus c=corpus(roster("张甲")+appointment("专职安全员","张甲","110101199001010011","",""));Rule r=count("专职安全员","=","1","专职安全员人数为1人",Map.of());assertEquals("PASS",evaluate(c,people(c),r).status());}
    @Test void strictMinimumDoesNotAcceptEquality(){EvidenceCorpus c=corpus(roster("张甲")+appointment("专职安全员","张甲","110101199001010011","",""));Rule r=count("专职安全员",">","1","专职安全员超过1人",Map.of());assertEquals("FAIL",evaluate(c,people(c),r).status());}
    @Test void strictUpperBoundRejectsEqualityEvenWithoutCompleteList(){EvidenceCorpus c=corpus(appointment("专职安全员","张甲","110101199001010011","",""));Rule r=count("专职安全员","<","1","专职安全员少于1人",Map.of());assertEquals("FAIL",evaluate(c,people(c),r).status());}
}
